  "<div class=\"scWrap\"><div class=\"scGrid\">{0}\n    <button data-rw=\"1\" title=\"Rastgele taraflar ve ordularla 1-3 cephe açar (mevcut meydanda)\"><b>Rastgele savaşlar</b><small>1-3 cephe, rastgele ordular</small></button></div>\n    <div id=\"scNow\">{1}</div></div>": "<div class=\"scWrap\"><div class=\"scGrid\">{0}\n    <button data-rw=\"1\" title=\"Opens 1-3 fronts with random sides and armies (on the current field)\"><b>Random wars</b><small>1-3 fronts, random armies</small></button></div>\n    <div id=\"scNow\">{1}</div></div>",
  "<div class=\"spArmy{0}\">\n        <div class=\"spHead\">{1}{2}<span class=\"spL\">Düzen</span><select id=\"spF\">{3}</select><span id=\"spMsg\"></span></div>\n        <div class=\"spTop\"><span id=\"spTot\"></span><button data-mul=\"0\" title=\"Bütün sayıları sıfırla\">Sıfırla</button></div>\n        <div class=\"spUnits\">{4}</div>\n        <div class=\"spAct\"><div class=\"spPreRow\"><select id=\"spPre\">{5}{6}</select>\n          <button data-mul=\"0.5\" title=\"Bütün sayıları yarıya indir\">×½</button><button data-mul=\"2\" title=\"Bütün sayıları ikiye katla\">×2</button></div>\n          {7}\n          <button data-s=\"armyPaint\" class=\"{8}\" title=\"Basılı tutup sürükle: geçtiğin yere birer birer dizilir. Birliği karta tıklayarak seç\">Fırçayla çiz · {9}</button></div>\n      </div>": "<div class=\"spArmy{0}\">\n        <div class=\"spHead\">{1}{2}<span class=\"spL\">Formation</span><select id=\"spF\">{3}</select><span id=\"spMsg\"></span></div>\n        <div class=\"spTop\"><span id=\"spTot\"></span><button data-mul=\"0\" title=\"Reset all numbers\">Reset</button></div>\n        <div class=\"spUnits\">{4}</div>\n        <div class=\"spAct\"><div class=\"spPreRow\"><select id=\"spPre\">{5}{6}</select>\n          <button data-mul=\"0.5\" title=\"Halve all numbers\">×½</button><button data-mul=\"2\" title=\"Double all numbers\">×2</button></div>\n          {7}\n          <button data-s=\"armyPaint\" class=\"{8}\" title=\"Hold and drag: units are placed one by one along your path. Pick the unit by clicking its card\">Paint · {9}</button></div>\n      </div>",
