  "<div class=\"uc{0}\" data-u=\"{1}\" title=\"{2} · tekerlek ya da −/+ (Shift: 10'ar) · fırça için karta tıkla\">\n          <canvas></canvas><div class=\"un\">{3}</div>\n          <div class=\"uq\"><button data-d=\"-1\">−</button><input type=\"number\" min=\"0\" max=\"{4}\" value=\"{5}\"><button data-d=\"1\">+</button></div></div>": "<div class=\"uc{0}\" data-u=\"{1}\" title=\"{2} · wheel or −/+ (Shift: by 10) · click the card for the brush\">\n          <canvas></canvas><div class=\"un\">{3}</div>\n          <div class=\"uq\"><button data-d=\"-1\">−</button><input type=\"number\" min=\"0\" max=\"{4}\" value=\"{5}\"><button data-d=\"1\">+</button></div></div>",
